func (q *Queries) StandDownPathway(ctx context.Context, arg StandDownPathwayParams) (int64, error) {
	result, err := q.db.Exec(ctx, standDownPathway,
		arg.StoodDownAt,
		arg.StoodDownReason,
		arg.TenantID,
		arg.PathwayID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateEmergencyVisit = `-- name: UpdateEmergencyVisit :execrows
UPDATE emergency.visit
SET patient_id = $1::uuid,
    unidentified = $2,
    status = $3,
    location = $4,
    disposition = $5,
    disposed_at = $6::timestamptz,
    disposition_note = $7,
    receiving_service = $8,
    observation_started_at = $9::timestamptz,
    observation_ends_at = $10::timestamptz,
    medico_legal = $11,
    medico_legal_ref = $12,
    updated_at = $13,
    version = version + 1
WHERE tenant_id = $14
  AND visit_id = $15
  AND version = $16
`

type UpdateEmergencyVisitParams struct {
	PatientID            pgtype.UUID
	Unidentified         bool
	Status               string
	Location             string
	Disposition          string
	DisposedAt           pgtype.Timestamptz
	DispositionNote      string
	ReceivingService     string
	ObservationStartedAt pgtype.Timestamptz
	ObservationEndsAt    pgtype.Timestamptz
	MedicoLegal          bool
	MedicoLegalRef       string
	UpdatedAt            pgtype.Timestamptz
	TenantID             uuid.UUID
	VisitID              uuid.UUID
	ExpectedVersion      int64
}

// Guarded on the version, so two clinicians disposing at once do not both win.
func (q *Queries) UpdateEmergencyVisit(ctx context.Context, arg UpdateEmergencyVisitParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateEmergencyVisit,
		arg.PatientID,
		arg.Unidentified,
		arg.Status,
		arg.Location,
		arg.Disposition,
		arg.DisposedAt,
		arg.DispositionNote,
		arg.ReceivingService,
		arg.ObservationStartedAt,
		arg.ObservationEndsAt,
		arg.MedicoLegal,
		arg.MedicoLegalRef,
		arg.UpdatedAt,
		arg.TenantID,
		arg.VisitID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
